"use client";
import { useState } from "react";
import { AnimatedPrice } from "@rhs-ui/commerce/animated-price";
import { Button } from "@rhs-ui/primitives/button";
export type PricingPlan = {id:string;name:string;description:string;monthlyPrice:string | number;yearlyPrice:string | number;currency?:string;locale?:string;features:readonly string[];featured?:boolean;action:string};
export function PricingSection({plans,onSelect}:{plans:readonly PricingPlan[];onSelect:(planId:string,interval:"monthly"|"yearly")=>void}):React.JSX.Element {
  const [interval,setInterval]=useState<"monthly"|"yearly">("monthly");
  return <section data-slot="pricing-section" aria-label="Choose a plan" className="w-full py-6"><div role="group" aria-label="Billing interval" className="mx-auto mb-8 flex w-fit gap-1 rounded-full border border-border p-1">{(["monthly","yearly"] as const).map(value=><button type="button" key={value} aria-pressed={value===interval} onClick={()=>setInterval(value)} className="rounded-full px-5 py-2 text-sm capitalize aria-pressed:bg-foreground aria-pressed:text-background focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring">{value}</button>)}</div><div className="grid gap-5 md:grid-cols-2">{plans.map(plan=><article key={plan.id} className={`flex flex-col rounded-xl border p-7 ${plan.featured?"border-foreground bg-muted":"border-border bg-card"}`}><div className="flex items-center justify-between gap-3"><h3 className="text-lg font-medium">{plan.name}</h3>{plan.featured?<span className="rounded-full bg-foreground px-3 py-1 text-[10px] text-background">Featured</span>:null}</div><p className="mt-3 text-sm text-muted-foreground">{plan.description}</p><p className="my-7 text-4xl font-medium tracking-tight">{typeof (interval==="monthly"?plan.monthlyPrice:plan.yearlyPrice) === "number" ? <AnimatedPrice value={(interval==="monthly"?plan.monthlyPrice:plan.yearlyPrice) as number} currency={plan.currency} locale={plan.locale} /> : (interval==="monthly"?plan.monthlyPrice:plan.yearlyPrice)}<span className="ml-2 text-xs font-normal tracking-normal text-muted-foreground">/ {interval==="monthly"?"month":"year"}</span></p><ul className="mb-8 flex flex-col gap-3">{plan.features.map(feature=><li key={feature} className="flex gap-3 text-sm"><span aria-hidden="true">✓</span>{feature}</li>)}</ul><Button className="mt-auto w-full" variant={plan.featured?"default":"outline"} onClick={()=>onSelect(plan.id,interval)}>{plan.action}</Button></article>)}</div></section>;
}
